async function loadUsers(){const snap=await getDocs(query(collection(db,'users'),where('customerId','==',ctx.customerId)));ctx.users=snap.docs.map(d=>({id:d.id,...d.data()})).filter(u=>isClubRole(String(u.role||''))||u.role==='customer_admin'); all('[data-vmw-user-count]',String(ctx.users.filter(u=>u.active!==false).length)); const t=document.querySelector('#vmwUserList');t.innerHTML=ctx.users.length?`<table class="portal-table"><thead><tr><th>Name</th><th>E-Mail</th><th>Rolle</th><th>Status</th><th></th></tr></thead><tbody>${ctx.users.map(u=>`<tr><td>${esc(u.displayName||'–')}</td><td>${esc(u.email||'–')}</td><td>${esc(roleLabel(u.role))}</td><td>${u.active===false?'Gesperrt':'Aktiv'}</td><td>${isClubRole(u.role)?`<button class="table-action" data-edit-club-user="${u.id}">Bearbeiten</button> <button class="table-action secondary" data-invite-club-user="${u.id}">Zugangslink</button>${u.id!==ctx.user.uid?` <button class="table-action secondary" data-delete-club-user="${u.id}">Entfernen</button>`:''}`:'<span class="admin-subline">über HOGAsports verwaltet</span>'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Noch keine Vereinsmanager-Benutzer angelegt.</div>';t.querySelectorAll('[data-edit-club-user]').forEach(b=>b.onclick=()=>editUser(b.dataset.editClubUser));t.querySelectorAll('[data-invite-club-user]').forEach(b=>b.onclick=async()=>{try{await sendClubAccessMail({uid:b.dataset.inviteClubUser});hogaAlert('Zugangslink wurde versendet.')}catch(e){hogaAlert(e.message)}});t.querySelectorAll('[data-delete-club-user]').forEach(b=>b.onclick=async()=>{const u=ctx.users.find(x=>x.id===b.dataset.deleteClubUser);if(!u)return;if(!await hogaConfirm(`Zugang von ${u.displayName||u.email} wirklich vollständig entfernen?\n\nDer Benutzer kann sich danach nicht mehr am Vereinsmanager anmelden.`))return;try{await deleteClubUser({uid:u.id});await loadUsers();hogaAlert('Vereinsmanager-Zugang wurde vollständig entfernt.')}catch(e){hogaAlert(e.message)}})}
function editUser(id){const u=ctx.users.find(x=>x.id===id),f=document.querySelector('#vmwUserForm');f.hidden=false;f.elements.uid.value=u.id;f.elements.displayName.value=u.displayName||'';f.elements.email.value=u.email||'';f.elements.role.value=u.role;f.elements.active.value=String(u.active!==false)}
document.querySelector('#vmwNewUser')?.addEventListener('click',()=>{const f=document.querySelector('#vmwUserForm');f.reset();f.elements.uid.value='';f.hidden=false});document.querySelector('#vmwCancelUser')?.addEventListener('click',()=>document.querySelector('#vmwUserForm').hidden=true);
