function invoicePrintHtml(i,club,member){const addr=[member?.street, [member?.zip,member?.city].filter(Boolean).join(' ')].filter(Boolean).map(esc).join('<br>');return `<section class="invoice-page"><header><h1>${esc(club.name||ctx.customer?.name||'Verein')}</h1><div>${esc(club.street||'')}<br>${esc([club.zip,club.city].filter(Boolean).join(' '))}</div></header><div class="recipient"><strong>${esc(i.memberName||'')}</strong><br>${addr}</div><h2>Rechnung ${esc(i.invoiceNumber)}</h2><p>Beitragszeitraum: ${esc(i.billingLabel||i.billingYear||'')}</p><table><thead><tr><th>Leistung</th><th>Betrag</th></tr></thead><tbody><tr><td>${esc(i.feeName||'Mitgliedsbeitrag')}</td><td>${euro(i.amount)}</td></tr></tbody><tfoot><tr><th>Gesamtbetrag</th><th>${euro(i.amount)}</th></tr></tfoot></table><p>Fällig am: <strong>${esc(dateDE(i.dueDate))}</strong></p><p>${club.iban?`Bitte überweisen Sie den Betrag auf folgendes Konto:<br><strong>IBAN ${esc(club.iban)}</strong>${club.bic?` · BIC ${esc(club.bic)}`:''}${club.bankName?` · ${esc(club.bankName)}`:''}`:'Bitte beachten Sie die im Verein vereinbarte Zahlungsweise.'}</p><footer>${esc(club.email||'')}${club.phone?' · '+esc(club.phone):''}</footer></section>`}
async function printInvoices(items){if(!items.length)return hogaAlert('Keine Rechnungen ausgewählt.');const clubSnap=await getDoc(doc(db,'customers',ctx.customerId,'clubData','profile')),club=clubSnap.exists()?clubSnap.data():{},members=new Map((ctx.members||[]).map(m=>[m.id,m])),w=window.open('','_blank');if(!w)return hogaAlert('Bitte Pop-ups für HOGAsports zulassen.');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>HOGAsports Rechnungen</title><style>@page{size:A4;margin:16mm}body{font:14px Arial;color:#222;margin:0}.invoice-page{min-height:260mm;position:relative;page-break-after:always}.invoice-page:last-child{page-break-after:auto}header{display:flex;justify-content:space-between;border-bottom:3px solid #b42025;padding-bottom:14px}header h1{color:#b42025;margin:0}.recipient{margin:42px 0}h2{margin-top:30px}table{width:100%;border-collapse:collapse;margin:25px 0}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}th:last-child,td:last-child{text-align:right}footer{position:absolute;bottom:0;border-top:1px solid #ddd;width:100%;padding-top:10px;color:#666}</style></head><body>${items.map(i=>invoicePrintHtml(i,club,members.get(i.memberId))).join('')}</body></html>`);w.document.close();setTimeout(()=>w.print(),300)}
