let vmwWeek=weekStart(new Date()),vmwSelectedResource='';function weekStart(d){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x}const iso=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
const mins=t=>{const [h,m]=String(t||'00:00').split(':').map(Number);return h*60+m};const hhmm=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;

async function loadPenalties(){const el=document.querySelector('#vmwPenaltyList');if(!el)return;try{const r=await getClubPenalties({});ctx.penalties=r.data.penalties||[];ctx.reviewCandidates=r.data.reviewCandidates||[];renderPenalties();renderReviewCandidates()}catch(e){console.error(e);el.innerHTML='<div class="empty-state">Stornogebühren konnten nicht geladen werden.</div>'}}
function renderPenalties(){const el=document.querySelector('#vmwPenaltyList');if(!el)return;const rows=ctx.penalties||[],open=rows.filter(x=>x.status==='Offen');document.querySelector('[data-vmw-penalty-open]')?.replaceChildren(document.createTextNode(String(open.length)));document.querySelector('[data-vmw-penalty-sum]')?.replaceChildren(document.createTextNode(euro(open.reduce((a,x)=>a+Number(x.amount||0),0))));el.innerHTML=rows.length?`<table class="portal-table"><thead><tr><th>Art / Mitglied</th><th>Ressource / Termin</th><th>Betrag</th><th>Status</th><th>Zahlung / Rechnung</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${x.type==='noshow'?'No-Show':'Storno'}</strong><small class="admin-subline">${esc((x.memberNumber?x.memberNumber+' · ':'')+(x.memberName||'–'))}</small></td><td>${esc(x.resourceName||'–')}<small class="admin-subline">${esc(dateDE(x.date))}</small></td><td>${euro(x.amount)}</td><td><span class="vmw-status">${esc(x.status)}</span></td><td>${x.invoiceNumber?`Rechnung ${esc(x.invoiceNumber)}`:esc(x.paymentMethod||'–')}</td><td>${canManageInvoices()&&x.status==='Offen'?`<button class="table-action" data-penalty-invoice="${x.id}">Rechnung erstellen</button> <button class="table-action" data-penalty-paid="${x.id}">Direkt bezahlt</button> <button class="table-action secondary" data-penalty-waive="${x.id}">Erlassen</button>`:canManageInvoices()&&!x.invoiceId&&x.status!=='Rechnung erstellt'?`<button class="table-action secondary" data-penalty-open="${x.id}">Wieder öffnen</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Keine Gebührenvorgänge vorhanden.</div>';el.querySelectorAll('[data-penalty-invoice]').forEach(b=>b.onclick=async()=>{const x=rows.find(q=>q.id===b.dataset.penaltyInvoice);if(!await hogaConfirm(`Für ${x?.memberName||'dieses Mitglied'} eine Rechnung über ${euro(x?.amount)} erstellen?`))return;try{const r=await createPenaltyInvoice({id:b.dataset.penaltyInvoice});await Promise.all([loadPenalties(),loadInvoices()]);hogaAlert(`Rechnung ${r.data.invoiceNumber} wurde erstellt.`)}catch(e){hogaAlert(e.message)}});el.querySelectorAll('[data-penalty-paid]').forEach(b=>b.onclick=async()=>{const x=rows.find(q=>q.id===b.dataset.penaltyPaid);const method=await hogaPaymentMethod(x);if(!method)return;try{await setClubPenaltyStatus({id:x.id,status:'Bezahlt',paymentMethod:method});await Promise.all([loadPenalties(),loadFinance()]);hogaAlert(`Gebühr als bezahlt verbucht (${method}).`)}catch(e){hogaAlert(e.message)}});el.querySelectorAll('[data-penalty-waive]').forEach(b=>b.onclick=async()=>{if(!await hogaConfirm('Diese Gebühr wirklich erlassen?'))return;try{await setClubPenaltyStatus({id:b.dataset.penaltyWaive,status:'Erlassen'});await Promise.all([loadPenalties(),loadFinance()])}catch(e){hogaAlert(e.message)}});el.querySelectorAll('[data-penalty-open]').forEach(b=>b.onclick=async()=>{if(!await hogaConfirm('Diesen Vorgang wieder auf „Offen“ setzen? Eine vorhandene automatische Finanzbuchung wird entfernt.'))return;try{await setClubPenaltyStatus({id:b.dataset.penaltyOpen,status:'Offen'});await Promise.all([loadPenalties(),loadFinance()])}catch(e){hogaAlert(e.message)}})}
function reviewTiming(x){if(x.type!=='cancellation'||x.hoursBeforeStart==null)return '';const h=Number(x.hoursBeforeStart||0),whole=Math.floor(h),mins=Math.round((h-whole)*60);return `Storniert ${whole} Std.${mins?` ${mins} Min.`:''} vor Beginn · Frist ${Number(x.cancellationHours||0)} Std.`}
function renderReviewCandidates(){const el=document.querySelector('#vmwNoShowList');if(!el)return;const rows=ctx.reviewCandidates||[];el.innerHTML=rows.length?`<table class="portal-table"><thead><tr><th>Art</th><th>Mitglied</th><th>Ressource</th><th>Termin / Prüfung</th><th>Gebühr</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${x.type==='cancellation'?'Storno':'No-Show'}</strong></td><td><strong>${esc((x.memberNumber?x.memberNumber+' · ':'')+(x.memberName||'–'))}</strong></td><td>${esc(x.resourceName||'–')}</td><td>${esc(dateDE(x.date))}<small class="admin-subline">${esc(x.startTime)}–${esc(x.endTime)}</small>${x.type==='cancellation'?`<small class="admin-subline">${esc(reviewTiming(x))}</small>`:''}</td><td>${euro(x.amount)}</td><td>${canManageInvoices()?`<button class="table-action" data-review-confirm="${x.id}">${x.type==='cancellation'?'Storno bestätigen':'No-Show bestätigen'}</button> <button class="table-action secondary" data-review-dismiss="${x.id}">Erledigt / Ausblenden</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state compact">Keine Buchungen zur Prüfung vorhanden.</div>';el.querySelectorAll('[data-review-confirm]').forEach(b=>b.onclick=async()=>{const x=rows.find(q=>q.id===b.dataset.reviewConfirm);if(!x)return;const label=x.type==='cancellation'?'Storno':'No-Show';if(!await hogaConfirm(`${label} für ${x.memberName||'dieses Mitglied'} bestätigen? Dadurch entsteht ein offener Gebührenvorgang über ${euro(x.amount)}. Es wird noch keine Rechnung erstellt.`))return;try{if(x.type==='cancellation')await createCancellationPenalty({bookingId:x.id});else await createNoShowPenalty({bookingId:x.id});await loadPenalties();hogaAlert(`${label} wurde als offener Gebührenvorgang erfasst.`)}catch(e){hogaAlert(e.message)}});el.querySelectorAll('[data-review-dismiss]').forEach(b=>b.onclick=async()=>{const x=rows.find(q=>q.id===b.dataset.reviewDismiss);if(!x)return;if(!await hogaConfirm(`Diesen ${x.type==='cancellation'?'Storno-':'No-Show-'}Fall als erledigt ausblenden? Die Buchung bleibt in der Historie erhalten und es entsteht keine Gebühr.`))return;try{await dismissBookingReview({bookingId:x.id});await loadPenalties();hogaAlert('Der Fall wurde aus der Prüfliste ausgeblendet.')}catch(e){hogaAlert(e.message)}})}
function hogaPaymentMethod(x){return new Promise(resolve=>{const old=document.querySelector('#hoga-payment-dialog');old?.remove();const wrap=document.createElement('div');wrap.id='hoga-payment-dialog';wrap.className='hoga-dialog-backdrop';wrap.innerHTML=`<div class="hoga-dialog" role="dialog" aria-modal="true"><div class="hoga-dialog-head"><strong>Stornogebühr bezahlen</strong></div><div class="hoga-dialog-body"><p>${esc(x?.memberName||'Mitglied')} · <strong>${euro(x?.amount)}</strong></p><label class="field"><span>Zahlungsart</span><select id="hogaPenaltyPayment"><option value="Bar">Bar / Vereinskasse</option><option value="Überweisung">Überweisung</option><option value="PayPal">PayPal</option><option value="Sonstiges">Sonstiges</option></select></label></div><div class="hoga-dialog-actions"><button class="btn btn-secondary btn-small" type="button" data-cancel>Abbrechen</button><button class="btn btn-primary btn-small" type="button" data-ok>Als bezahlt verbuchen</button></div></div>`;document.body.appendChild(wrap);const done=v=>{wrap.remove();resolve(v)};wrap.querySelector('[data-cancel]').onclick=()=>done('');wrap.querySelector('[data-ok]').onclick=()=>done(wrap.querySelector('#hogaPenaltyPayment').value);wrap.addEventListener('click',e=>{if(e.target===wrap)done('')});wrap.querySelector('select').focus()})}

async function loadResources(){try{const r=await getResourceCalendar({weekStart:iso(vmwWeek)});ctx.resources=r.data.resources||[];ctx.bookings=r.data.bookings||[];const active=ctx.resources.filter(x=>x.active!==false);if(!active.some(x=>x.id===vmwSelectedResource))vmwSelectedResource=active[0]?.id||'';renderResourceList();renderResourceSelector();renderResourceCalendar()}catch(e){console.error(e);hogaAlert(e.message||'Ressourcen konnten nicht geladen werden.')}}
function renderResourceSelector(){const sel=document.querySelector('#vmwCalendarResource');if(!sel)return;const rs=(ctx.resources||[]).filter(r=>r.active!==false);sel.innerHTML=rs.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('');sel.value=vmwSelectedResource;sel.onchange=()=>{vmwSelectedResource=sel.value;renderResourceCalendar()}}
function renderResourceList(){const el=document.querySelector('#vmwResourceList');if(!el)return;el.innerHTML=ctx.resources?.length?`<table class="portal-table"><thead><tr><th>Ressource</th><th>Zeiten</th><th>Raster</th><th>Buchungsregeln</th><th>Storno / No-Show</th><th>Status</th><th></th></tr></thead><tbody>${ctx.resources.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small class="admin-subline">${esc(r.type||'')}</small></td><td>${esc(r.openTime)}–${esc(r.closeTime)}</td><td>${esc(r.slotMinutes)} Min.</td><td>${Number(r.bookAheadDays||0)?`${esc(r.bookAheadDays)} Tage voraus`:'ohne Vorlauf-Limit'}<small class="admin-subline">${Number(r.maxActiveBookings||0)?`max. ${esc(r.maxActiveBookings)} aktive Buchungen`:'aktive Buchungen unbegrenzt'}</small></td><td>${r.penaltyEnabled?`Storno: ${esc(r.cancellationHours)} Std. · ${euro(r.penaltyAmount)}`:'Storno: aus'}<small class="admin-subline">${r.noShowEnabled?`No-Show: ${euro(r.noShowAmount)}`:'No-Show: aus'}</small></td><td>${r.active===false?'Inaktiv':'Aktiv'}</td><td>${isVMAdmin()?`<button class="table-action" data-edit-resource="${r.id}">Bearbeiten</button> <button class="table-action secondary" data-delete-resource="${r.id}">Löschen</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Noch keine Ressourcen angelegt.</div>';el.querySelectorAll('[data-edit-resource]').forEach(b=>b.onclick=()=>editResource(b.dataset.editResource));el.querySelectorAll('[data-delete-resource]').forEach(b=>b.onclick=async()=>{if(!await hogaConfirm('Ressource wirklich löschen? Bestehende Buchungen verhindern das Löschen.'))return;try{await deleteClubResource({id:b.dataset.deleteResource});await loadResources()}catch(e){hogaAlert(e.message)}})}
function calendarHtml(r,days,bookings,admin=true){const slot=Math.max(15,Number(r.slotMinutes||60)),open=mins(r.openTime),close=mins(r.closeTime),rows=Math.ceil((close-open)/slot),rowH=34,total=rows*rowH;const times=Array.from({length:rows},(_,i)=>open+i*slot);return `<div class="outlook-calendar" style="--slot-h:${rowH}px"><div class="outlook-corner">Zeit</div>${days.map(d=>`<div class="outlook-day-head"><strong>${d.toLocaleDateString('de-DE',{weekday:'short'})}</strong><span>${d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</span></div>`).join('')}<div class="outlook-times" style="height:${total}px">${times.map((t,i)=>`<span style="top:${i*rowH}px">${hhmm(t)}</span>`).join('')}</div>${days.map(d=>{const date=iso(d),bs=bookings.filter(b=>b.date===date&&b.status!=='cancelled');return `<div class="outlook-day-col" data-cal-date="${date}" style="height:${total}px">${times.map((t,i)=>`<button type="button" class="outlook-slot" style="top:${i*rowH}px;height:${rowH}px" data-cal-book="${r.id}" data-date="${date}" data-time="${hhmm(t)}" aria-label="${date} ${hhmm(t)} buchen"></button>`).join('')}${bs.map(b=>{const top=((mins(b.startTime)-open)/slot)*rowH,height=Math.max(22,((mins(b.endTime)-mins(b.startTime))/slot)*rowH-2),label=b.bookingType==='block'?(b.title||'Gesperrt'):(b.memberName||b.title||'Buchung');return `<div class="outlook-booking ${b.bookingType==='block'?'is-block':''}" style="top:${top}px;height:${height}px"><strong>${esc(b.startTime)}–${esc(b.endTime)}</strong><span>${esc(label)}</span>${admin?`<button type="button" data-cancel-booking="${b.id}" title="Stornieren">×</button>`:''}</div>`}).join('')}</div>`}).join('')}</div>`}
function renderResourceCalendar(){const el=document.querySelector('#vmwResourceCalendar');if(!el)return;const days=[0,1,2,3,4,5,6].map(n=>{const d=new Date(vmwWeek);d.setDate(d.getDate()+n);return d});document.querySelector('#vmwWeekLabel').textContent=`${days[0].toLocaleDateString('de-DE')} – ${days[6].toLocaleDateString('de-DE')}`;const r=(ctx.resources||[]).find(x=>x.id===vmwSelectedResource&&x.active!==false);if(!r){el.innerHTML='<div class="empty-state">Bitte zuerst eine aktive Ressource anlegen.</div>';return}const bs=(ctx.bookings||[]).filter(b=>b.resourceId===r.id);el.innerHTML=`<div class="calendar-resource-title"><strong>${esc(r.name)}</strong><span>${esc(r.openTime)}–${esc(r.closeTime)} · ${esc(r.slotMinutes)}-Min.-Raster</span></div>${calendarHtml(r,days,bs,true)}`;el.querySelectorAll('[data-cal-book]').forEach(b=>b.onclick=()=>openBlock(b.dataset.calBook,b.dataset.date,b.dataset.time));el.querySelectorAll('[data-cancel-booking]').forEach(b=>b.onclick=async e=>{e.stopPropagation();if(!await hogaConfirm('Buchung/Sperrung stornieren?'))return;try{await cancelClubBooking({id:b.dataset.cancelBooking});await loadResources()}catch(e){hogaAlert(e.message)}})}
function editResource(id){const r=ctx.resources.find(x=>x.id===id),f=document.querySelector('#vmwResourceForm');f.reset();for(const [k,v] of Object.entries(r||{}))if(f.elements[k])f.elements[k].value=String(v);f.elements.id.value=id||'';f.hidden=false}document.querySelector('#vmwNewResource')?.addEventListener('click',()=>editResource(''));document.querySelector('#vmwCancelResource')?.addEventListener('click',()=>document.querySelector('#vmwResourceForm').hidden=true);document.querySelector('#vmwResourceForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));d.penaltyEnabled=d.penaltyEnabled==='true';d.noShowEnabled=d.noShowEnabled==='true';d.active=d.active==='true';try{await saveClubResource(d);f.hidden=true;await loadResources();hogaAlert('Ressource gespeichert.')}catch(x){hogaAlert(x.message)}});
function openBlock(resourceId,date,startTime=''){const f=document.querySelector('#vmwBlockForm'),r=ctx.resources.find(x=>x.id===resourceId);f.reset();f.elements.resourceId.value=resourceId;f.elements.date.value=date;f.elements.dateDisplay.value=`${date} · ${r?.name||''}`;f.elements.startTime.value=startTime||r?.openTime||'08:00';const n=mins(f.elements.startTime.value)+Number(r?.slotMinutes||60);f.elements.endTime.value=hhmm(n);f.hidden=false;f.scrollIntoView({behavior:'smooth',block:'center'})}document.querySelector('#vmwCancelBlock')?.addEventListener('click',()=>document.querySelector('#vmwBlockForm').hidden=true);document.querySelector('#vmwBlockForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));try{await createClubBooking(d);f.hidden=true;await loadResources();hogaAlert('Kalendereintrag gespeichert.')}catch(x){hogaAlert(x.message)}});document.querySelector('#vmwPrevWeek')?.addEventListener('click',()=>{vmwWeek.setDate(vmwWeek.getDate()-7);loadResources()});document.querySelector('#vmwNextWeek')?.addEventListener('click',()=>{vmwWeek.setDate(vmwWeek.getDate()+7);loadResources()});document.querySelector('#vmwToday')?.addEventListener('click',()=>{vmwWeek=weekStart(new Date());loadResources()});

async function loadAccessModule(){if(!ctx.accessModule)return;try{const r=await getAccessModuleData({});ctx.accessPoints=r.data.accessPoints||[];ctx.accessEvents=r.data.events||[];renderAccessModule()}catch(e){console.error(e);hogaAlert(e.message||'Zutrittsmodul konnte nicht geladen werden.')}}
function renderAccessModule(){const keys=(ctx.members||[]).filter(m=>m.digitalKeyEnabled===true);all('[data-access-key-count]',String(keys.length));all('[data-access-point-count]',String((ctx.accessPoints||[]).filter(x=>x.active!==false).length));all('[data-access-event-count]',String((ctx.accessEvents||[]).length));const kp=document.querySelector('#vmwDigitalKeyList');if(kp)kp.innerHTML=keys.length?`<table class="portal-table"><thead><tr><th>Mitglied</th><th>Nr.</th><th>Status</th><th>Schlüssel-ID</th></tr></thead><tbody>${keys.map(m=>`<tr><td><strong>${esc(`${m.firstName||''} ${m.lastName||''}`.trim())}</strong></td><td>${esc(m.memberNumber||'–')}</td><td><span class="vmw-key-state is-active">Freigegeben</span></td><td><span class="admin-subline">${m.digitalKeyId?'vorbereitet':'wird beim Speichern erzeugt'}</span></td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Noch keinem Mitglied wurde ein digitaler Schlüssel freigegeben.</div>';const ap=document.querySelector('#vmwAccessPointList');if(ap)ap.innerHTML=(ctx.accessPoints||[]).length?`<table class="portal-table"><thead><tr><th>Zutrittspunkt</th><th>Funktion</th><th>Hardware</th><th>Status</th><th></th></tr></thead><tbody>${ctx.accessPoints.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.mode==='both'?'Zutritt + Check-in':x.mode==='checkin'?'Check-in':'Tür / Zutritt')}</td><td>${esc(x.deviceLabel||'noch nicht zugeordnet')}</td><td>${x.active===false?'Inaktiv':'Aktiv'}</td><td>${isVMAdmin()?`<button class="table-action" data-edit-access="${x.id}">Bearbeiten</button> <button class="table-action secondary" data-delete-access="${x.id}">Entfernen</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Noch keine Zutrittspunkte angelegt.</div>';ap?.querySelectorAll('[data-edit-access]').forEach(b=>b.onclick=()=>editAccessPoint(b.dataset.editAccess));ap?.querySelectorAll('[data-delete-access]').forEach(b=>b.onclick=async()=>{if(!await hogaConfirm('Zutrittspunkt wirklich entfernen? Bereits protokollierte Ereignisse bleiben später in der Historie erhalten.'))return;try{await deleteAccessPoint({id:b.dataset.deleteAccess});await loadAccessModule()}catch(e){hogaAlert(e.message)}});const ev=document.querySelector('#vmwAccessEventList');if(ev&&ctx.accessEvents?.length)ev.innerHTML=`<table class="portal-table"><thead><tr><th>Zeit</th><th>Mitglied</th><th>Zutrittspunkt</th><th>Ergebnis</th></tr></thead><tbody>${ctx.accessEvents.map(x=>`<tr><td>${esc(x.occurredAtText||'–')}</td><td>${esc(x.memberName||'–')}</td><td>${esc(x.accessPointName||'–')}</td><td>${esc(x.result||'–')}</td></tr>`).join('')}</tbody></table>`}
function editAccessPoint(id=''){const f=document.querySelector('#vmwAccessPointForm');if(!f)return;f.reset();const x=(ctx.accessPoints||[]).find(a=>a.id===id);if(x)for(const [k,v] of Object.entries(x))if(f.elements[k])f.elements[k].value=String(v);f.elements.id.value=id;f.hidden=false;f.scrollIntoView({behavior:'smooth',block:'center'})}
document.querySelector('#vmwNewAccessPoint')?.addEventListener('click',()=>editAccessPoint(''));document.querySelector('#vmwCancelAccessPoint')?.addEventListener('click',()=>document.querySelector('#vmwAccessPointForm').hidden=true);document.querySelector('#vmwAccessPointForm')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f));d.active=d.active==='true';try{await saveAccessPoint(d);f.hidden=true;await loadAccessModule();hogaAlert('Zutrittspunkt gespeichert.')}catch(x){hogaAlert(x.message)}});document.querySelector('[data-vmw-tab="access"]')?.addEventListener('click',loadAccessModule);

document.querySelector('[data-vmw-tab="resources"]')?.addEventListener('click',()=>{loadResources();loadPenalties()});
